63	Future<void> _loadSession(String sessionId, Emitter<ChatState> emit, {required bool isOffline}) async {
64	  final result = await _chatRepository.listMessages(sessionId);
65	  result.match(
66	    (failure) {
67	      if (failure is AuthExpiredFailure) _reauthController.add(null);
68	      final cached = _chatRepository.cachedMessages(sessionId);
69	      if (cached == null) {
70	        // Never opened while online — "the standard no-connection state instead of any content"
71	        // (Edge Cases) — only reachable here, never for the empty/no-session state above.
72	        emit(ChatReady(
73	          sessionId: sessionId, messages: const [], isOffline: isOffline,
74	          awaitingResponse: false, loadFailure: failure,
75	        ));
76	      } else {
77	        emit(ChatReady(sessionId: sessionId, messages: cached, isOffline: isOffline, awaitingResponse: false));
78	      }
79	    },
80	    (messages) async {
81	      await _chatRepository.setLastActiveSessionId(sessionId);
82	      emit(ChatReady(sessionId: sessionId, messages: messages, isOffline: isOffline, awaitingResponse: false));
83	    },
84	  );
85	}
