90	```dart
91	Future<void> _onMessageSubmitted(MessageSubmitted event, Emitter<ChatState> emit) async {
92	  final current = state;
93	  if (current is! ChatReady || !current.canSend) return;   // composer was disabled; defensive no-op
94	
95	  if (!await _connectivityChecker.hasConnection()) {        // FR-012 — blocked client-side, never attempted
96	    return;   // composer's own isOffline flag (R8's live stream) will reflect this on its own shortly
97	  }
98	
99	  final generation = ++_turnGeneration;
100	  final now = DateTime.now();
101	  final optimisticUser = ChatMessage(
102	    id: 'local-${now.microsecondsSinceEpoch}', sessionId: current.sessionId ?? '',
103	    role: ChatRole.user, content: event.text, seq: current.messages.length,
104	    status: ChatMessageStatus.complete, retryCount: 0, createdAt: now,
105	  );
106	  final optimisticAssistant = ChatMessage(
107	    id: 'local-${now.microsecondsSinceEpoch}-response', sessionId: current.sessionId ?? '',
108	    role: ChatRole.assistant, content: '', seq: current.messages.length + 1,
109	    status: ChatMessageStatus.streaming, retryCount: 0, createdAt: now,
110	  );
111	  emit(current.copyWith(
112	    messages: [...current.messages, optimisticUser, optimisticAssistant],
113	    awaitingResponse: true,
114	  ));
115	
116	  String sessionId;
117	  if (current.sessionId == null) {
118	    final created = await _chatRepository.createSession(title: ChatTitleDeriver.derive(event.text));
119	    final maybeId = created.match((f) => null, (s) => s.id);
120	    if (maybeId == null) {
121	      if (generation != _turnGeneration) return;
122	      _failTurn(emit, created.getLeft().toNullable()!, optimisticUserId: optimisticUser.id, optimisticAssistantId: optimisticAssistant.id);
123	      return;
124	    }
125	    sessionId = maybeId;
126	    await _chatRepository.setLastActiveSessionId(sessionId);
127	  } else {
128	    sessionId = current.sessionId!;
129	  }
130	
131	  final stream = _chatRepository.sendMessage(sessionId: sessionId, content: event.text);
132	  await _consumeTurn(
133	    stream, emit, generation: generation, sessionId: sessionId,
134	    optimisticUserId: optimisticUser.id, optimisticAssistantId: optimisticAssistant.id,
135	  );
136	}
