142	Future<void> _onMessageRetryRequested(MessageRetryRequested event, Emitter<ChatState> emit) async {
143	  final current = state;
144	  if (current is! ChatReady || current.awaitingResponse || current.sessionId == null) return;
145	  final index = current.messages.indexWhere(
146	    (m) => m.role == ChatRole.assistant && m.status == ChatMessageStatus.failed &&
147	        _userMessageIdFor(current.messages, m) == event.userMessageId,
148	  );
149	  if (index == -1) return;
150	  if (!await _connectivityChecker.hasConnection()) return;   // FR-012
151	
152	  final generation = ++_turnGeneration;
153	  final now = DateTime.now();
154	  final placeholder = ChatMessage(
155	    id: 'local-${now.microsecondsSinceEpoch}-retry', sessionId: current.sessionId!,
156	    role: ChatRole.assistant, content: '', seq: current.messages[index].seq,
157	    status: ChatMessageStatus.streaming, retryCount: current.messages[index].retryCount + 1,
158	    createdAt: now,
