1	# Contract: `ApiClient.sseStream` (`lib/core/network/api_client.dart`, `lib/core/network/sse_frame.dart`)
2	
3	Extends `ApiClient` (F000/RF01) in place. `call()` is unchanged. This is a `core/network/` addition, not
4	chat-specific — any future SSE-consuming unit reuses it as-is (research.md R1).
5	
6	```dart
7	class SseFrame extends Equatable {
8	  const SseFrame({required this.event, required this.data});
9	  final String event;
10	  final String data;
11	  @override List<Object?> get props => [event, data];
12	}
13	
14	extension on ApiClient {
15	  Stream<Either<Failure, SseFrame>> sseStream(
16	    String function, {
17	    required String method,
18	    Map<String, dynamic>? body,
19	    List<String>? pathSegments,
20	    AuthMode authMode = AuthMode.userSession,
21	  }) async* {
22	    final baseUrl = dotenv.env['FUNCTIONS_BASE_URL'] ?? '';
23	    final segments = [function, ...?pathSegments];
24	    final url = '$baseUrl/${segments.join('/')}';
25	    final bearer = authMode == AuthMode.anonKey
26	        ? _anonKey
27	        : (await _tokenStorage.readAccessToken() ?? '');
28	
29	    try {
30	      final response = await _dio.request<ResponseBody>(
31	        url,
32	        data: body,
33	        options: Options(
34	          method: method,
35	          responseType: ResponseType.stream,
36	          headers: {'apikey': _anonKey, 'Authorization': 'Bearer $bearer'},
37	        ),
38	      );
39	
40	      final buffer = StringBuffer();
41	      await for (final chunk in response.data!.stream) {
42	        buffer.write(utf8.decode(chunk, allowMalformed: true));
43	        var text = buffer.toString();
44	        while (text.contains('\n\n')) {
45	          final splitIndex = text.indexOf('\n\n');
46	          final rawFrame = text.substring(0, splitIndex);
47	          text = text.substring(splitIndex + 2);
48	          final frame = _parseFrame(rawFrame);
49	          if (frame != null) yield Right(frame);
50	        }
51	        buffer
52	          ..clear()
53	          ..write(text);
54	      }
55	    } on DioException catch (e) {
56	      yield Left(_mapException(e));   // the exact existing _mapException() call() already uses
57	    }
58	  }
59	
60	  SseFrame? _parseFrame(String rawFrame) {
61	    String? event;
62	    final dataLines = <String>[];
63	    for (final line in rawFrame.split('\n')) {
64	      if (line.startsWith('event:')) {
65	        event = line.substring(6).trim();
66	      } else if (line.startsWith('data:')) {
67	        dataLines.add(line.substring(5).trim());
68	      }
69	      // any other SSE field (id:, retry:, comments starting with ':') is ignored —
70	      // this backend's contract never sends them (openapi.yaml's own documented sequence).
71	    }
72	    if (event == null) return null;
73	    return SseFrame(event: event, data: dataLines.join('\n'));
74	  }
75	}
76	```
77	
78	- Exactly one `Left(Failure)` is ever yielded, and only as the stream's **last** item, then the stream closes
79	  (`async*` returning after the `yield Left(...)` inside the `catch` — no further iteration of
